// @ts-nocheck
// Generated by scripts/port-home.py from design/home.html. Client behaviour for the homepage.
export function initHome(raEl: HTMLElement): () => void {
  let alive = true;
  const timers: number[] = [];
  const raf = (f) => { if (alive) requestAnimationFrame(f); };

  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const css = n => getComputedStyle(raEl).getPropertyValue(n).trim();
  const sg=(t,a,b)=>Math.max(0,Math.min(1,(t-a)/(b-a))), ez=v=>1-Math.pow(1-v,3), eio=v=>v<.5?4*v*v*v:1-Math.pow(-2*v+2,3)/2;

  /* ---------- wordmark: each line fills the width; letters rise in and respond to the cursor ---------- */
  const nameBox = document.querySelector('.name');
  const lines = [...document.querySelectorAll('[data-fit]')];
  let li = 0;
  lines.forEach(el => { const t = el.textContent; el.textContent = ''; [...t].forEach(ch => { const s = document.createElement('span'); s.textContent = ch; s.style.setProperty('--i', li++); el.appendChild(s); }); });
  if (!reduce) nameBox.classList.add('intro-anim');
  function fit(){ lines.forEach(el => { const box = el.parentElement.getBoundingClientRect().width; el.style.fontSize = '100px';
    const w = el.getBoundingClientRect().width; if (w) el.style.fontSize = (100 * box / w * 0.995) + 'px'; }); }
  (document.fonts && document.fonts.ready ? document.fonts.ready : Promise.resolve()).then(fit);
  new ResizeObserver(fit).observe(nameBox);
  if (!reduce && matchMedia('(hover: hover)').matches){
    nameBox.addEventListener('pointermove', e => { lines.forEach(el => [...el.children].forEach(s => {
      const r = s.getBoundingClientRect(), d = Math.hypot(e.clientX-(r.left+r.width/2), e.clientY-(r.top+r.height/2)) / r.height;
      const k = Math.exp(-d*d*1.6); s.style.fontVariationSettings = `"wdth" ${125 - 40*k}, "wght" ${800 - 600*k}`; })); });
    nameBox.addEventListener('pointerleave', () => lines.forEach(el => [...el.children].forEach(s => s.style.fontVariationSettings = '')));
  }

  /* ---------- Jaipur clock ---------- */
  const clock = document.getElementById('clock');
  const tick = () => { try { clock.textContent = new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(new Date()) + ' IST'; } catch(e){} };
  tick(); timers.push(setInterval(tick, 20000));

  /* ---------- scroll reveals (content stays visible; only position eases in) ---------- */
  const revealEls = [...document.querySelectorAll('.sh, .rv')];
  if (!reduce && 'IntersectionObserver' in window){
    const vh = innerHeight;
    revealEls.forEach(el => { if (el.getBoundingClientRect().top < vh * .92) el.classList.add('in'); });
    document.documentElement.classList.add('motion');
    const io = new IntersectionObserver(es => es.forEach(en => { if (en.isIntersecting){ en.target.classList.add('in'); io.unobserve(en.target); } }), {rootMargin:'0px 0px -8% 0px'});
    revealEls.forEach(el => { if (!el.classList.contains('in')) io.observe(el); });
  }

  /* ---------- MediFast agent run: map + steps, synced ---------- */
  const steps=[...document.querySelectorAll('#agent li')], reply=document.getElementById('reply'), rp=document.getElementById('replay');
  const mc=document.getElementById('pmap'), mx=mc.getContext('2d');
  const PH=[[.18,.28],[.72,.2],[.62,.76],[.3,.78],[.86,.48],[.1,.6],[.48,.14]], STOCK=[0,2,4], PICK=4, STEP_T=[.3,1.4,2.0,2.8,3.4], END=3.9;
  let MW=0,MH=0, start=-1e9;
  const sz=()=>{ const b=mc.getBoundingClientRect(), d=Math.min(2,devicePixelRatio||1); MW=b.width; MH=b.height; mc.width=MW*d; mc.height=MH*d; mx.setTransform(d,0,0,d,0,0); };
  new ResizeObserver(sz).observe(mc); sz();
  function drawMap(now){
    const t=(now-start)/1000, k=Math.min(t,END+1), rani=css('--rani'), indigo=css('--indigo'), mari=css('--marigold'), rule=css('--rule'), mu=css('--muted'), panel=css('--panel'), mono=css('--mono');
    mx.clearRect(0,0,MW,MH); mx.strokeStyle=rule; mx.lineWidth=1;
    for(let i=1;i<6;i++){ const y=MH*i/6+Math.sin(i)*6; mx.beginPath(); mx.moveTo(0,y); mx.lineTo(MW,y+8); mx.stroke(); }
    for(let i=1;i<9;i++){ const x=MW*i/9+Math.cos(i)*8; mx.beginPath(); mx.moveTo(x,0); mx.lineTo(x-10,MH); mx.stroke(); }
    const ux=MW*.45, uy=MH*.52, sc=sg(k,.6,1.6);
    if(sc>0&&sc<1){ mx.globalAlpha=1-sc; mx.strokeStyle=indigo; mx.lineWidth=1.5; mx.beginPath(); mx.arc(ux,uy,sc*MW*.6,0,7); mx.stroke(); mx.globalAlpha=1; }
    const found=ez(sg(k,1.6,2.2)), go=ez(sg(k,2.2,3.0)), conf=ez(sg(k,3.0,3.4));
    const px=MW*PH[PICK][0], py=MH*PH[PICK][1];
    if(go>0){ mx.strokeStyle=rani; mx.lineWidth=2; mx.setLineDash([6,5]); mx.lineDashOffset=-now/40; mx.beginPath(); mx.moveTo(ux,uy); mx.lineTo(ux+(px-ux)*go,uy+(py-uy)*go); mx.stroke(); mx.setLineDash([]); }
    PH.forEach(([fx,fy],i)=>{ const x=MW*fx,y=MH*fy, st=STOCK.includes(i);
      mx.globalAlpha = st ? 1 : 1-found*.55; mx.fillStyle = i===PICK&&conf>0 ? rani : (st&&found>.5 ? indigo : mu);
      mx.fillRect(x-8,y-8,16,16); mx.fillStyle=panel; mx.fillRect(x-1.5,y-5,3,10); mx.fillRect(x-5,y-1.5,10,3); });
    mx.globalAlpha=1; mx.fillStyle=mari; mx.beginPath(); mx.arc(ux,uy,6.5,0,7); mx.fill();
    mx.strokeStyle=mari; mx.globalAlpha=.5; mx.beginPath(); mx.arc(ux,uy,12+Math.sin(now/260)*2.5,0,7); mx.stroke(); mx.globalAlpha=1;
    mx.font=`500 11px ${mono}`; mx.textAlign='center'; mx.fillStyle=mari; mx.fillText('you',ux,uy+26);
    if(conf>0){ const lab='600 m · ready'; const w=mx.measureText(lab).width+16, bx=Math.min(MW-w-8,px-w/2), by=py-34;
      mx.globalAlpha=conf; mx.fillStyle=rani; mx.fillRect(bx,by,w,20); mx.fillStyle=panel; mx.textAlign='left'; mx.fillText(lab,bx+8,by+14); mx.globalAlpha=1; }
    if(t<=END+.5){ steps.forEach((li,i)=>li.classList.toggle('done', t>=STEP_T[i])); reply.style.opacity = t>=END-.2 ? 1 : 0; reply.style.transform = t>=END-.2 ? 'none' : 'translateY(8px)'; rp.disabled = t<END; }
  }
  rp.addEventListener('click', () => { if(reduce) return; start=performance.now(); });

  /* ---------- Yatra Sync: riders matched onto one route, fare split ---------- */
  const yc=document.getElementById('ymap'), yx=yc.getContext('2d'), yrp=document.getElementById('yreplay'), fareRows=[...document.querySelectorAll('#fare tbody tr, #fare tfoot tr')];
  const N=[[.07,.74],[.24,.6],[.31,.28],[.5,.44],[.52,.82],[.69,.22],[.77,.58],[.93,.34]];
  const E=[[0,1],[1,2],[1,3],[2,3],[3,4],[4,6],[3,6],[2,5],[5,6],[5,7],[6,7],[0,4]];
  const ROUTE=[0,1,2,5,7], RIDERS=[[0,'A'],[2,'B'],[5,'C']], Y_ROW_T=[2.7,3.05,3.4,3.8], Y_END=4.4;
  let YW=0,YH=0, ystart=-1e9;
  const ysz=()=>{ const b=yc.getBoundingClientRect(), d=Math.min(2,devicePixelRatio||1); YW=b.width; YH=b.height; yc.width=YW*d; yc.height=YH*d; yx.setTransform(d,0,0,d,0,0); };
  new ResizeObserver(ysz).observe(yc); ysz();
  const segs=[]; let total=0; for(let i=0;i<ROUTE.length-1;i++){ const a=N[ROUTE[i]], b=N[ROUTE[i+1]]; const l=Math.hypot(b[0]-a[0],(b[1]-a[1])*.56); segs.push([a,b,l]); total+=l; }
  function along(f){ let d=f*total; for(const [a,b,l] of segs){ if(d<=l){ const u=l?d/l:0; return [a[0]+(b[0]-a[0])*u, a[1]+(b[1]-a[1])*u]; } d-=l; } return N[ROUTE[ROUTE.length-1]]; }
  function drawYatra(now){
    const t=(now-ystart)/1000, k=Math.min(t,Y_END+1), rani=css('--rani'), indigo=css('--indigo'), mari=css('--marigold'), rule=css('--rule'), mu=css('--muted'), panel=css('--panel'), ink=css('--ink'), mono=css('--mono');
    yx.clearRect(0,0,YW,YH); yx.lineCap='round';
    yx.strokeStyle=rule; yx.lineWidth=6; E.forEach(([i,j])=>{ yx.beginPath(); yx.moveTo(N[i][0]*YW,N[i][1]*YH); yx.lineTo(N[j][0]*YW,N[j][1]*YH); yx.stroke(); });
    N.forEach(([x,y])=>{ yx.fillStyle=mu; yx.beginPath(); yx.arc(x*YW,y*YH,2.5,0,7); yx.fill(); });
    const drawn=eio(sg(k,.8,2.2));
    if(drawn>0){ yx.strokeStyle=indigo; yx.lineWidth=3; yx.beginPath(); yx.moveTo(N[ROUTE[0]][0]*YW,N[ROUTE[0]][1]*YH);
      const steps=60; for(let s=1;s<=steps*drawn;s++){ const p=along(s/steps); yx.lineTo(p[0]*YW,p[1]*YH); } yx.stroke(); }
    const dest=N[ROUTE[ROUTE.length-1]];
    yx.fillStyle=ink; yx.fillRect(dest[0]*YW-9,dest[1]*YH-9,18,18); yx.fillStyle=panel; yx.font=`500 10px ${mono}`; yx.textAlign='center'; yx.fillText('✈',dest[0]*YW,dest[1]*YH+4);
    yx.fillStyle=ink; yx.fillText('Airport',dest[0]*YW,dest[1]*YH-16);
    RIDERS.forEach(([n,l],i)=>{ const p=ez(sg(k,.1+i*.18,.5+i*.18)); if(!p) return; const x=N[n][0]*YW, y=N[n][1]*YH;
      yx.globalAlpha=p; yx.fillStyle=rani; yx.beginPath(); yx.arc(x,y,11*p,0,7); yx.fill(); yx.fillStyle=panel; yx.font=`500 11px ${mono}`; yx.fillText(l,x,y+4); yx.globalAlpha=1; });
    const cabF=eio(sg(k,2.2,Y_END)); if(cabF>0){ const p=along(cabF); yx.fillStyle=mari; yx.fillRect(p[0]*YW-10,p[1]*YH-7,20,14); yx.fillStyle=ink; yx.fillRect(p[0]*YW-6,p[1]*YH-4,12,4); }
    if(t<=Y_END+.5){ fareRows.forEach((r,i)=>r.classList.toggle('wait', t<Y_ROW_T[i])); yrp.disabled = t<Y_END; }
  }
  yrp.addEventListener('click', () => { if(reduce) return; ystart=performance.now(); });

  /* play each demo once when it first scrolls into view; otherwise they rest in their finished state */
  if (!reduce && 'IntersectionObserver' in window){
    const playIO = new IntersectionObserver(es => es.forEach(en => { if(!en.isIntersecting) return; playIO.unobserve(en.target);
      if(en.target.id==='medi-demo') start=performance.now(); else ystart=performance.now(); }), {threshold:.45});
    playIO.observe(document.getElementById('medi-demo')); playIO.observe(document.getElementById('yatra-demo'));
  }
  if(reduce){ drawMap(performance.now()); drawYatra(performance.now()); }
  else { (function loop(now){ drawMap(now); drawYatra(now); raf(loop); })(performance.now()); }

  /* ---------- copy email ---------- */
  const cp = document.getElementById('copy'), em = document.getElementById('email');
  cp.addEventListener('click', () => { const t = em.textContent;
    const ok = () => { cp.textContent='Copied'; setTimeout(()=>cp.textContent='Copy email',1600); };
    const fb = () => { const r=document.createRange(); r.selectNodeContents(em); const s=getSelection(); s.removeAllRanges(); s.addRange(r); cp.textContent='Selected, press Ctrl+C'; };
    try { navigator.clipboard.writeText(t).then(ok, fb); } catch(e){ fb(); } });

  return () => { alive = false; timers.forEach(clearInterval); document.documentElement.classList.remove('motion'); };
}
